require_once('phpass-0.3/PasswordHash.php');

define('PHPASS_HASH_STRENGTH', 8);
define('PHPASS_HASH_PORTABLE', false);

/**
 * SimpleLoginSecure Class
 *
 * Makes authentication simple and secure.
 *
 */
class SimpleLoginSecure
{
	var $CI;
	var $user_table = 'users';
	var $lead_table = 'assign_leads';
	var $module_table = 'assign_modules';
 
	/**
	 * Create a user account
	 *
	 * @access	public
	 * @param	string
	 * @param	string
	 * @param	bool
	 * @return	bool
	 */
	function create($name='',$email = '', $password = '', $phone_number='',$type=1,$directNumber,$title,$ext,$flag,$emailSignature='',$mobileNumber='',$profilePic='' ,$auto_login = true) 
	{
		$this->CI =& get_instance();
		


		//Make sure account info was sent
		if($email == '' OR $password == '') {
			return false;
		}
		
		//Check against user table
		$this->CI->db->where('email', $email); 
		$query = $this->CI->db->get_where($this->user_table);
		
		if ($query->num_rows() > 0) //email already exists
			return false;

		//Hash password using phpass
		$hasher = new PasswordHash(PHPASS_HASH_STRENGTH, PHPASS_HASH_PORTABLE);
		$password_hashed = $hasher->HashPassword($password);

		//Insert account into the database
		$data = array(
					'name' =>$name,
					'email' => $email,
					'password' => $password_hashed,
					'phone_number' => $phone_number,
					'type'	=> $type,
					'ext' =>$ext,
					'flag'=>$flag,
					'title'=>$title,
					'direct_number'=>$directNumber,
					'email_for_signature'=>$emailSignature,
					'mobile_number'=>$mobileNumber,
					'profile_pic'=>$profilePic,
					'user_date' => date('c'),
					'user_modified' => date('c'),
				);		
		$this->CI->db->set($data); 

		if(!$this->CI->db->insert($this->user_table)){
			//echo $this->CI->db->last_query();
			return false;	
		}
								
				
		if($auto_login)
			$this->login($email, $password);
		
		return true;
	}

	/**
	 * Update a user account
	 *
	
	 * @access	public
	 * @param integer
	 * @param	string
	 * @param	bool
	 * @return	bool
	 */
	function update($id = null, $password='',$profile_pic='',$phoneNumber,$directNumber,$mobileNumber,$email_for_signature,$ext,$title, $auto_login = true) 
	{
		$this->CI =& get_instance();

		//Make sure account info was sent
		if($id == null) {
			return false;
		}
		
		//Check against user table
		$this->CI->db->where('id', $id);
		$query = $this->CI->db->get_where($this->user_table);
		
		if ($query->num_rows() == 0){ // user don't exists
			return false;
		}

		$hasher = new PasswordHash(PHPASS_HASH_STRENGTH, PHPASS_HASH_PORTABLE);
		$password_hashed = $hasher->HashPassword($password);
		//Update account into the database
		$data = array(
					'password' => $password_hashed,
					'phone_number' => $phoneNumber,
					'direct_number' => $directNumber,
					'mobile_number' => $mobileNumber,
					'email_for_signature' => $email_for_signature,
					'profile_pic' => $profile_pic,
					'ext' =>$ext,
					'title'=>$title,
					'user_modified' => date('Y-m-d H:i:m'),
				);
		$this->CI->db->where('id', $id);

		if(!$this->CI->db->update($this->user_table, $data)) //There was a problem! 
			return false;		
		
		if($auto_login){
			$this->CI->db->where('id', $id);
			$query = $this->CI->db->get_where($this->user_table);
			if ($query->num_rows() > 0){ 
				$user_data['user'] = (array)$query->first_row(); 
				
			}	
			unset($user_data['google_token']);
			/*$user_data['email'] = $user_data['user']->email;*/
			$user_data['modules_assign'] = $this->getAllModules($id);
			$user_data['logged_in'] = true;
			if(!isset($_SESSION)){
				session_start();
			}			
			$user_data['phone_number'] = $phoneNumber; // for compatibility with Simplelogin
			$user_data['direct_number'] = $directNumber; // for compatibility with Simplelogin
			$user_data['mobile_number'] = $mobileNumber; // for compatibility with Simplelogin
			$user_data['email_for_signature'] = $email_for_signature; // for compatibility with Simplelogin
			if(isset($_SESSION['find_user']) && !empty($_SESSION['find_user']['type'])){
				$_SESSION['find_user'] = $user_data;
			}
			$this->CI->session->set_userdata($user_data);			
		}
		return true;
	}

